-- a few thin strata lit from below by the coming sun
local st = noise{seed=101, period=120, octaves=4, stretch={0.0, 7}, warp={90, 10}}
strata = mask(function(x, y)
  local band = math.exp(-((y - 250) / 55)^2) + 0.7 * math.exp(-((y - 330) / 22)^2)
  local v = st(x, y) * 0.9 + 0.35 * band - 0.28
  return smoothstep(0.02, 0.22, v) * smoothstep(150, 200, y) * (1 - smoothstep(360, 395, y))
end)
print(strata:area())
work(strata, {hand="scumble", pal=skypal, angle=function(x, y) return 0.02 * math.sin(x / 150) end, length={40, 120}, coverage=2.2, medium=0.5,
  edge="lost", color=function(x, y)
    local g = math.exp(-((x - 690) / 380)^2)
    return mix(mix("#a49dab", "#c9aeb0", smoothstep(210, 360, y)), "#dbbfae", 0.4 * g * smoothstep(250, 360, y))
  end})
EOF
